# Compute count of column 'Notes' grouped by 'Title'
print(f"🔧 Computing count of 'Notes' grouped by 'Title'")

# Check if columns exist and operation is valid
if 'Notes' not in df.columns:
    print(f"❌ Error: Column 'Notes' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Title' not in df.columns:
    print(f"❌ Error: Group by column 'Title' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "count" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'count'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "count" == "count":
            result = df.groupby('Title')['Notes'].count()
        elif "count" == "sum":
            result = df.groupby('Title')['Notes'].sum()
        elif "count" == "avg":
            result = df.groupby('Title')['Notes'].mean()
        elif "count" == "min":
            result = df.groupby('Title')['Notes'].min()
        elif "count" == "max":
            result = df.groupby('Title')['Notes'].max()

        print(f"✅ Count of 'Notes' by 'Title':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Title', f'count_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped count: {e}")
        print(f"Column dtypes: {df[['Notes', 'Title']].dtypes}")
